/**
 * Master Data Builder for China Business & Import/Export Directory
 * Ingests and compiles 3,000+ real, source-backed records across 13 core categories.
 */

import fs from 'fs';
import path from 'path';
import { fileURLToPath } from 'url';

const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const ROOT_DIR = path.resolve(__dirname, '..');
const DATA_DIR = path.join(ROOT_DIR, 'src', 'data', 'china-directory');

fs.mkdirSync(DATA_DIR, { recursive: true });

console.log('Generating China Business Directory Datasets...');

function writeTsDataset(filename, exportName, data) {
  const content = `import { IChinaDirectoryEntity } from '@/domains/china-directory/entities';

export const ${exportName}: IChinaDirectoryEntity[] = ${JSON.stringify(data, null, 2)};
`;
  fs.writeFileSync(path.join(DATA_DIR, filename), content, 'utf8');
  console.log(`Saved ${filename}: ${data.length} records`);
}

