// Combine all cities
const ALL_CITIES_RAW = [...RAW_CITIES];

for (const group of ADDITIONAL_PROVINCES) {
  const pData = PROVINCE_LOOKUP[group.prov] || { ar: group.prov, en: group.prov, zh: group.prov, lat: 34.0, lng: 110.0 };
  for (const c of group.cities) {
    ALL_CITIES_RAW.push({
      slug: c.slug,
      ar: c.ar,
      en: c.en,
      zh: c.zh,
      pinyin: c.en,
      prov: group.prov,
      lat: pData.lat + (Math.random() - 0.5) * 1.5,
      lng: pData.lng + (Math.random() - 0.5) * 1.5,
      ind: c.ind,
      tag: `${c.ind[0]} والصناعات المرتبطة`
    });
  }
}

console.log(`Aggregated total unique cities: ${ALL_CITIES_RAW.length}`);

